mapper.sql:
select 'RECHARGE' as biz_type, '充值入账' as biz_type_label, r.recharge_no as biz_no, null as order_no, null as instrument_id, null as instrument_name, u.department_id as department_id, d.dept_name as department_name, r.user_id as user_id, u.real_name as user_name, r.amount as amount, 'IN' as inout_type, '收入' as inout_type_label, r.remark as remark,
coalesce(r.audit_time, r.create_time) as occur_time from biz_recharge_order r left join sys_user u on u.id = r.user_id left join sys_department d on d.id = u.department_id where r.status = 'PASS' and (#{bizType} is null or #{bizType} = '' or #{bizType} = 'RECHARGE') and (#{inoutType} is null or #{inoutType} = '' or #{inoutType} = 'IN')
and coalesce(r.audit_time, r.create_time) >= #{startTime}
and coalesce(r.audit_time, r.create_time) <= #{endTime}
and u.department_id = #{departmentId}
and u.department_id = #{scopeDepartmentId}
union all
select 'SETTLEMENT' as biz_type, '仪器收费' as biz_type_label, s.settlement_no as biz_no, o.order_no as order_no, s.instrument_id as instrument_id, i.instrument_name as instrument_name, o.department_id as department_id, d.dept_name as department_name, o.user_id as user_id, u.real_name as user_name, s.final_amount as amount, 'IN' as inout_type, '收入' as inout_type_label, s.price_desc as remark,
coalesce(s.settled_time, s.create_time) as occur_time from biz_settlement_record s left join biz_reservation_order o on o.id = s.order_id left join biz_instrument i on i.id = s.instrument_id left join sys_department d on d.id = o.department_id left join sys_user u on u.id = o.user_id where s.settle_status = 'CONFIRMED' and (#{bizType} is null or #{bizType} = '' or #{bizType} = 'SETTLEMENT') and (#{inoutType} is null or #{inoutType} = '' or #{inoutType} = 'IN')
and coalesce(s.settled_time, s.create_time) >= #{startTime}
and coalesce(s.settled_time, s.create_time) <= #{endTime}
and s.instrument_id = #{instrumentId}
and o.department_id = #{departmentId}
and o.department_id = #{scopeDepartmentId}
union all
select 'REFUND' as biz_type, '订单退款' as biz_type_label, s.settlement_no as biz_no, o.order_no as order_no, s.instrument_id as instrument_id, i.instrument_name as instrument_name, o.department_id as department_id, d.dept_name as department_name, o.user_id as user_id, u.real_name as user_name, s.final_amount as amount, 'OUT' as inout_type, '支出' as inout_type_label, '订单退款' as remark,
coalesce(s.settled_time, s.create_time) as occur_time from biz_settlement_record s left join biz_reservation_order o on o.id = s.order_id left join biz_instrument i on i.id = s.instrument_id left join sys_department d on d.id = o.department_id left join sys_user u on u.id = o.user_id where s.settle_status = 'REFUNDED' and (#{bizType} is null or #{bizType} = '' or #{bizType} = 'REFUND') and (#{inoutType} is null or #{inoutType} = '' or #{inoutType} = 'OUT')
and coalesce(s.settled_time, s.create_time) >= #{startTime}
and coalesce(s.settled_time, s.create_time) <= #{endTime}
and s.instrument_id = #{instrumentId}
and o.department_id = #{departmentId}
and o.department_id = #{scopeDepartmentId}
union all
select 'MAINTENANCE_EXPENSE' as biz_type, '维护支出' as biz_type_label, e.expense_no as biz_no, null as order_no, e.instrument_id as instrument_id, i.instrument_name as instrument_name, e.department_id as department_id, d.dept_name as department_name, null as user_id, null as user_name, e.amount as amount, 'OUT' as inout_type, '支出' as inout_type_label, concat(coalesce(e.title, ''), ifnull(concat('：', e.remark), '')) as remark, e.expense_time as occur_time from biz_finance_expense e left join biz_instrument i on i.id = e.instrument_id left join sys_department d on d.id = e.department_id where 1 = 1 and (#{bizType} is null or #{bizType} = '' or #{bizType} = 'MAINTENANCE_EXPENSE') and (#{inoutType} is null or #{inoutType} = '' or #{inoutType} = 'OUT')
and e.expense_time >= #{startTime}
and e.expense_time <= #{endTime}
and e.instrument_id = #{instrumentId}
and e.department_id = #{departmentId}
and e.department_id = #{scopeDepartmentId}

