select * from (
) t where 1 = 1
and ( t.biz_no like concat('%', #{keyword}, '%') or t.order_no like concat('%', #{keyword}, '%') or t.instrument_name like concat('%', #{keyword}, '%') or t.department_name like concat('%', #{keyword}, '%') or t.user_name like concat('%', #{keyword}, '%') or t.remark like concat('%', #{keyword}, '%') )
order by t.occur_time desc, t.biz_type desc limit #{offset}, #{pageSize}

select count(1) from (
) t where 1 = 1
and ( t.biz_no like concat('%', #{keyword}, '%') or t.order_no like concat('%', #{keyword}, '%') or t.instrument_name like concat('%', #{keyword}, '%') or t.department_name like concat('%', #{keyword}, '%') or t.user_name like concat('%', #{keyword}, '%') or t.remark like concat('%', #{keyword}, '%') )
